<?php
/** ACC-009-QA. PHP 8.0; source files only. Owner CLI from public_html;
 * stage this runner privately outside public_html. No DB/config/API bootstrap.
 * --dry-run | --apply | --rollback-check=/absolute/backup | --rollback=/absolute/backup
 * Backups: ../_patch_backups/ACC-009-QA-<UTC>-<random>/0.source..2.source
 * Roll back this follow-up BEFORE rolling back its parent C1+H1 installation.
 * Rollback checks ALL targets/backups before writing, accepts partial application
 * only when each target matches an exact before/after image, and preserves drift.
 * Template cache cleanup is owner packet work after this runner exits zero.
 */
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
const QA_SPEC='';
const QA_READ='';
function qa_fail(string $code): void { throw new RuntimeException($code); }
function qa_out(string $key,string $value): void { echo $key.'='.$value."\n"; }
function qa_path(string $base,string $rel,bool $file=true): string {
    if (!preg_match('~^[A-Za-z0-9_./-]+$~D',$rel) || strpos($rel,'..')!==false || $rel[0]==='/') qa_fail('unsafe_relative_path');
    $p=$base;
    foreach(explode('/',$rel) as $part) {
        if ($part==='') qa_fail('empty_path_part'); $p.='/'.$part;
        if (is_link($p)) qa_fail('linked_path');
    }
    if ($file && !is_file($p)) qa_fail('missing_file:'.$rel);
    return $p;
}
function qa_sha(string $p): string { $v=hash_file('sha256',$p);if(!is_string($v))qa_fail('hash_failed');return $v; }
function qa_read(string $p): string { $v=file_get_contents($p);if(!is_string($v))qa_fail('read_failed');return $v; }
function qa_write_new(string $p,string $body,int $mode): void {
    $h=fopen($p,'xb');if($h===false)qa_fail('exclusive_create_failed');
    try {if(!chmod($p,$mode))qa_fail('chmod_failed');$n=0;$len=strlen($body);while($n<$len){$w=fwrite($h,substr($body,$n));if(!$w)qa_fail('write_failed');$n+=$w;}if(!fflush($h))qa_fail('flush_failed');}finally{fclose($h);}
}
function qa_replace(string $p,string $body,int $mode,string $expected): void {
    if(is_link($p)||!is_file($p)||qa_sha($p)!==$expected)qa_fail('concurrent_target_drift');
    $temp=dirname($p).'/.ACC-009-QA-'.bin2hex(random_bytes(8)).'.tmp';
    try{qa_write_new($temp,$body,$mode);if(qa_sha($temp)!==hash('sha256',$body))qa_fail('temp_hash_failed');if(qa_sha($p)!==$expected)qa_fail('concurrent_target_drift');if(!rename($temp,$p))qa_fail('atomic_replace_failed');}finally{if(is_file($temp)&&!is_link($temp))unlink($temp);}
}
function qa_lint(string $p): void {
    $lines=[];$code=0;exec(escapeshellarg(PHP_BINARY).' -n -l '.escapeshellarg($p).' 2>&1',$lines,$code);
    if($code!==0)qa_fail('host_php_lint_failed');
}
function qa_spec(): array {
    $s=json_decode(base64_decode(QA_SPEC,true),true,32,JSON_THROW_ON_ERROR);
    if(count($s)!==3)qa_fail('bad_spec');
    foreach($s as &$row){$raw=base64_decode($row['payload'],true);$body=$raw===false?false:gzuncompress($raw);if(!is_string($body)||hash('sha256',$body)!==$row['after'])qa_fail('payload_hash');$row['body']=$body;}
    return $s;
}
function qa_inspect(string $root,array $spec,bool $mixed): array {
    $states=[];
    foreach($spec as $i=>$row){$p=qa_path($root,$row['target']);$sha=qa_sha($p);if($sha!==$row['before']&&$sha!==$row['after'])qa_fail('target_drift:'.$row['target']);$states[$i]=$sha;}
    if(!$mixed&&count(array_unique(array_map(function($i)use($states,$spec){return $states[$i]===$spec[$i]['before']?'before':'after';},array_keys($spec))))!==1)qa_fail('mixed_targets_requires_reviewed_recovery');
    return $states;
}
function qa_self_delete(): void {
    $self=__FILE__;if(is_link($self)||!is_file($self)||!unlink($self))qa_fail('self_delete_failed_source_may_have_changed');qa_out('self_deleted','yes');
}
function qa_rollback(string $root,array $spec,string $backup,bool $check): void {
    $base=qa_path(dirname($root),'_patch_backups',false);
    if(!is_dir($base)||is_link($base)||!preg_match('~^'.preg_quote($base,'~').'/ACC-009-QA-[0-9]{8}T[0-9]{6}Z-[a-f0-9]{8}$~D',$backup)||str_replace('\\','/',(string)realpath($backup))!==$backup||is_link($backup))qa_fail('invalid_backup_path');
    $m=json_decode(qa_read(qa_path($backup,'manifest.json')),true,16,JSON_THROW_ON_ERROR);
    if(($m['task']??'')!=='ACC-009-QA'||($m['root']??'')!==$root||count($m['files']??[])!==3)qa_fail('backup_manifest_contract');
    $states=qa_inspect($root,$spec,true);$bodies=[];
    foreach($spec as $i=>$row){$r=$m['files'][$i];if(($r['target']??'')!==$row['target']||($r['before']??'')!==$row['before']||($r['after']??'')!==$row['after']||!is_int($r['mode']??null)||$r['mode']<0||$r['mode']>0777)qa_fail('backup_manifest_identity');$p=qa_path($backup,$i.'.source');if(qa_sha($p)!==$row['before'])qa_fail('backup_drift');$bodies[$i]=qa_read($p);}
    qa_out('rollback_preflight','ok_all_targets_and_all_backups');
    if($check){qa_out('done','ok');return;}
    // All required originals are admitted before the first restoration.
    foreach($spec as $i=>$row){if($states[$i]===$row['before'])continue;qa_replace(qa_path($root,$row['target']),$bodies[$i],$m['files'][$i]['mode'],$row['after']);qa_lint(qa_path($root,$row['target']));qa_out('restored_file',$row['target']);}
    foreach($spec as $row)if(qa_sha(qa_path($root,$row['target']))!==$row['before'])qa_fail('restore_verification');
    qa_out('rollback','ok');qa_self_delete();qa_out('done','ok');
}
try {
    umask(0077);
    if(PHP_MAJOR_VERSION!==8||PHP_MINOR_VERSION!==0)qa_fail('php80_required');
    $mode=$argv[1]??'';if($argc!==2||!($mode==='--dry-run'||$mode==='--apply'||strpos($mode,'--rollback=')===0||strpos($mode,'--rollback-check=')===0))qa_fail('usage');
    $root=str_replace('\\','/',(string)getcwd());if(str_replace('\\','/',(string)realpath($root))!==$root||basename($root)!=='public_html'||is_link($root))qa_fail('cwd_public_html_required');
    $self=str_replace('\\','/',(string)realpath(__FILE__));if(strpos($self,$root.'/')===0)qa_fail('private_stage_required');
    qa_out('task','ACC-009-QA');qa_out('mode',explode('=',$mode,2)[0]);qa_out('time',gmdate('c'));
    $spec=qa_spec();qa_lint(__FILE__);qa_out('runner_php_lint','ok');
    if(strpos($mode,'--rollback')===0){qa_rollback($root,$spec,explode('=',$mode,2)[1],strpos($mode,'--rollback-check=')===0);exit(0);}
    $deps=json_decode(base64_decode(QA_READ,true),true,16,JSON_THROW_ON_ERROR);
    foreach($deps as $d)if(qa_sha(qa_path($root,$d['target']))!==$d['sha256'])qa_fail('dependency_drift:'.$d['target']);
    qa_out('dependencies','ok_'.count($deps));
    $states=qa_inspect($root,$spec,false);
    foreach($spec as $row){$source=qa_read(qa_path($root,$row['target']));if(hash('sha256',$source)===$row['before'])foreach($row['anchors'] as $anchor)if(substr_count($source,$anchor['text'])!==$anchor['count'])qa_fail('anchor_count:'.$row['target']);}
    qa_out('source_preflight','ok');
    foreach($spec as $i=>$row)qa_out('target_'.$i,$row['target'].'|'.$states[$i].'|'.$row['after']);
    if($states[0]===$spec[0]['after']){qa_out('already_applied','yes');if($mode==='--apply')qa_self_delete();qa_out('done','ok');exit(0);}
    if($mode==='--dry-run'){qa_out('would_change_files','3');qa_out('db_access','NONE');qa_out('done','ok');exit(0);}
    $base=qa_path(dirname($root),'_patch_backups',false);
    if(!file_exists($base)&&!mkdir($base,0700))qa_fail('backup_base_create');
    if(is_link($base)||!is_dir($base)||str_replace('\\','/',(string)realpath($base))!==$base)qa_fail('backup_base_unsafe');
    $backup=$base.'/ACC-009-QA-'.gmdate('Ymd\THis\Z').'-'.bin2hex(random_bytes(4));if(!mkdir($backup,0700))qa_fail('backup_create');
    $manifest=['task'=>'ACC-009-QA','root'=>$root,'files'=>[]];$before=[];
    foreach($spec as $i=>$row){$p=qa_path($root,$row['target']);if(qa_sha($p)!==$row['before'])qa_fail('backup_target_drift');$before[$i]=qa_read($p);$modeBits=fileperms($p)&0777;qa_write_new($backup.'/'.$i.'.source',$before[$i],0600);if(qa_sha($backup.'/'.$i.'.source')!==$row['before'])qa_fail('backup_hash');$manifest['files'][]=['target'=>$row['target'],'before'=>$row['before'],'after'=>$row['after'],'mode'=>$modeBits];}
    qa_write_new($backup.'/manifest.json',json_encode($manifest,JSON_THROW_ON_ERROR|JSON_PRETTY_PRINT)."\n",0600);qa_out('backup_path',$backup);
    $written=[];
    try{
        foreach($spec as $i=>$row){$p=qa_path($root,$row['target']);qa_replace($p,$row['body'],$manifest['files'][$i]['mode'],$row['before']);$written[]=$i;qa_lint($p);if(qa_sha($p)!==$row['after'])qa_fail('after_hash');qa_out('target',$row['target']);qa_out('sha256_before',$row['before']);qa_out('backup',$backup.'/'.$i.'.source');qa_out('syntax_gate','ok_nonPHP_target');qa_out('sha256_after',$row['after']);qa_out('changed_file',$row['target']);}
        foreach($spec as $i=>$row){if(qa_sha(qa_path($root,$row['target']))!==$row['after'])qa_fail('final_drift');qa_out('after_'.$i,$row['target'].'|'.$row['after']);}
    }catch(Throwable $e){
        foreach(array_reverse($written) as $i){$row=$spec[$i];$p=qa_path($root,$row['target']);qa_replace($p,$before[$i],$manifest['files'][$i]['mode'],$row['after']);qa_out('auto_restored_file',$row['target']);}
        qa_out('auto_restore','ok');throw $e;
    }
    qa_out('host_php_lint','ok');qa_out('lint_scope','runner_and_nonPHP_target_syntax_only_not_Twig_compilation');qa_out('db_access','NONE');qa_self_delete();qa_out('done','ok');
}catch(Throwable $e){fwrite(STDERR,'error='.$e->getMessage()."\n");exit(1);}
